; ============================================================================
; AdLib music and sound-effect driver (ADLIB.DAT), Sound Images 1991
; ============================================================================
; Canonical decompressed image, 22,125 bytes, rebuilt byte for byte. All
; addresses in this file are driver offsets in hexadecimal. The image has no
; relocations: every data access uses DS=CS (the services select it) and every
; jump/call is relative, so it runs at whatever segment DOS allocated.
;
; C TRANSLATION READINESS: READY for the whole music/effect engine (0000..059F
; with its state and payload) over the canonical driver memory layout. Bounding
; dependencies, all outside the engine: OPL output (WriteOplRegister 0559 and
; the detection status reads) is a platform service; update cadence is owned
; by the main program; stream tokens 88..AF are a characterized corrupted-
; control escape that native code reports as an unsupported state.
; Translated: c/adlib_engine.c (all instructions of 0000..059F except the
; UNKNOWN bytes 0014 and 05A0..05A7), differential suite tests/adlib_engine.py.
; Native boundary: every OUT/IN of 0559 and of the detection status reads is
; one LmnOplPorts callback in original order (port taken live from [08A3]);
; 88..AF return LMN_ADLIB_ENGINE_STREAM_ESCAPE at 01EA before JMP [SI].
; Arithmetic flags inside a service are unobservable (every exit is IRET).
;
; ---------------------------------------------------------------------------
; Lifetime and installation (main program side)
; ---------------------------------------------------------------------------
; Main CS:054E is the only installer. It allocates 0567h paragraphs (CS:0570,
; carry not checked), points INT 61h at allocation:0000 (CS:057B) and then
; decodes ADLIB.DAT into the block (CS:058D), so the vector is live before the
; image is loaded. It then calls AH=01 detection (CS:059D). On success the block
; and vector stay for the whole process: no later path reloads, frees or
; re-points them, and nothing restores the old INT 61h vector at exit. On
; failure the same block is overwritten with TANDYSND.DAT (CS:05CA) and the
; Tandy driver answers INT 61h instead. The pinned image occupies 566Dh of the
; 5670h allocated bytes.
;
; The driver owns no interrupt and has no timer of its own. All state lives in
; this image and persists from load to process exit; reset and song start
; rewrite selected fields only (see each routine), they never create fresh
; state. INT 61h clears IF and TF on entry and no driver instruction sets IF, so
; each service runs to its IRET without being interrupted by the game timer.
; Separate INT 61h calls are still separate transactions: for example a timer
; update can run between the main program's song request (AH=03) and its
; following explicit update (AH=00).
;
; ---------------------------------------------------------------------------
; INT 61h interface (dispatcher 0000)
; ---------------------------------------------------------------------------
;   AH=00 UpdateService 0115   one engine step: song request, effect request,
;                              then one visit of all nine channels.
;   AH=01 DetectService 00A3   OPL timer detection. Returns AL=01 found / 00 not,
;                              AH=21, BX=8000h|(first status & E0), CX=0,
;                              DX=0388. Other registers preserved.
;   AH=02 ResetService 003A    stop music, silence all operators, deactivate all
;                              nine channels. Pending effect request survives.
;   AH=03 SetCommand3Latch     pending song request ED := AL (0 = none).
;   AH=04 SetCommand4Latch     pending effect request F0 := AL (0 = none).
;   AH=05 SetCommand5Latch     current-song gate EE := AL (no main caller).
;   AH>=06                     IRET with AH decremented five times, AL intact.
; AL is never validated by the setters; the update validates IDs (song 01..15h,
; effect 01..12h). Recognized services return AH=00 with AL unchanged, except
; detection. All services preserve DS, ES, SS and the caller's flags (IRET), use
; the caller's stack (at most 36 bytes including the interrupt frame, in AH=00)
; and never execute CLD/STD: the caller's DF is kept. String reads (reset table,
; song header) assume DF=0. DF=1 has no legitimate producer: the only STD of the
; main program (CS:1BB0, inside the DAT decoder) is cleared before that routine
; returns, no INT 61h is issued inside it, and the game timer that issues AH=00
; is not installed while DAT files are read.
;
; Main-program callers: AH=00 from the game timer handler (main CS:1872, once
; per handler invocation while the AdLib path and a sound option are enabled)
; and right after a song request (CS:03BE); AH=02 at CS:029F and CS:030F; AH=03
; at CS:03B9 with the level song ID byte DS:0054 (chosen from the level music
; table CS:4877 or the special-level table CS:4888); AH=04 at seventeen effect
; sites; AH=01 at CS:059D. There is no AH=05 caller.
;
; ---------------------------------------------------------------------------
; Request latches (00ED..00F0)
; ---------------------------------------------------------------------------
;   ED  pending song ID (AH=03). Cleared when taken and by every music stop.
;   EE  current song ID; nonzero blocks new song requests. Set by song start,
;       cleared together with ED by StopMusicChannels (reset, command 83,
;       invalid song ID).
;   EF  song-request scratch: set from ED at 0461 and cleared at 0473 inside one
;       update, so it is 0 between services.
;   F0  pending effect ID (AH=04). Cleared when an effect channel is granted;
;       invalid or unservable IDs stay latched. One byte: the last write wins.
; Consequence: while a song is current, AH=03 cannot replace it. The request
; waits in ED and is discarded when music stops, because every stop clears ED
; together with EE; shipped songs never stop by themselves.
;
; ---------------------------------------------------------------------------
; Update cadence (UpdateService 0115)
; ---------------------------------------------------------------------------
; Each AH=00: ProcessSongRequest, ProcessEffectRequest, DEC tempo phase B6B,
; then AdvanceChannel for records 05AC,05C0,...,064C in that order, then if the
; phase is 0 reload it from the tempo reload B6A. Mode-2 (effect) channels
; advance on every update; mode-1 (music) channels only on updates where the
; phase reached 0, i.e. once every tempo-reload updates (reload 0 means 256).
; Song start sets the phase to 1, so the new song's first events happen in the
; same update. An effect granted in an update is fetched immediately and then
; visited again by the same update's scan.
;
; One channel tick (AdvanceChannel 0177): decrement countdown +01. At 0, fetch
; stream tokens until a timed event. Otherwise apply the pitch slide
; (StepChannelPitch) and the release check (ReleaseBeforeNextEvent).
;
; ---------------------------------------------------------------------------
; Channel records: 9 x 14h bytes at 05AC (adlib_Channels)
; ---------------------------------------------------------------------------
;   +00 note       last note byte, changed by slides modulo 256
;   +01 countdown  ticks left in the current event
;   +02 word       instrument record pointer (0000 until the first C token)
;   +04 instrument ID (token-C0); written, never read
;   +05 op0, +06 op1   OPL operator offsets (modulator, carrier); fixed
;   +07 OPL channel 0..8; fixed
;   +08 word       key-off packet: AL=register B0+channel, AH=block/F-number
;                  high bits without the key-on bit; written by the pitch
;                  routine, sent to silence the channel
;   +0A word       pointer to the NEXT word of the order list
;   +0C word       pointer to the next stream byte
;   +0E            last level operand (B-token value or instrument +0A); never read
;   +0F            carrier level bias (instrument +0B)
;   +10 mode       0 inactive, 1 music, 2 effect
;   +11 duration   ticks per timed event, set by E0..FF (1..32)
;   +12 transpose  signed note offset (instrument +08 or command 84)
;   +13 slide      per-tick note step: 00 none, 01 up, FF down
; Fixed operator/channel tuples as loaded: (00,03,0) (01,04,1) (02,05,2)
; (08,0B,3) (09,0C,4) (0A,0D,5) (10,13,6) (11,14,7) (12,15,8); +08 starts as
; B0+channel/00 and every other byte as 0. Records 0..3 play music (song start
; activates the first channel-count records; shipped songs have 3 or 4
; channels). Record 4 (05FC) is never activated by shipped data. Records 5..8
; are effect channels. Instrument bank choice depends on the record address,
; not the mode: below 05FC the song bank [B68], from 05FC up the effect bank 54E3.
; Deactivation clears only the mode; everything else is retained and later
; read again (note, duration, transpose, slide, instrument pointer).
;
; ---------------------------------------------------------------------------
; Song container (payload 0B6E..54E2)
; ---------------------------------------------------------------------------
; Directory 0B6E: 21 absolute header words; song ID n reads word [0B6C+2n].
; Header: +0 word copied to 05A8 (never read; values 4000/4200/4312/4400),
; +2 word instrument bank offset from 0B6E, +4 byte tempo reload, +5 byte
; channel count, +6 one word per channel: order list offset from 0B6E.
; Order list: words, each a pattern offset from 0B6E, ended by a zero word and
; a redirect word (list offset from 0B6E). Command 80 at a zero follows the
; redirect once and plays its first pattern; song start does not test for zero.
; Every shipped list redirects to its own start, so songs loop forever.
; Effects: directory 55E3 holds absolute stream words for IDs 01..12h (slot 0
; unused); effects have no header or order list and use the effect bank 54E3.
; Song titles come from the test-jukebox menu at 0660 (strongly supported, see
; adlib_UnusedJukeboxScreenText): 01 Awesome, 02 BeastI, 03 BeastII, 04 CanCan,
; 05 Doggie, 06..08 Lemming1..3, 09 Menace, 0A Mountain, 0B Ten Lemmings,
; 0C..15 Tim1..Tim10.
;
; ---------------------------------------------------------------------------
; Stream grammar (fetch loop StreamFetch 019E)
; ---------------------------------------------------------------------------
; BX walks the stream with 16-bit wrap; there is no length or loop guard.
; Controls continue fetching within the same tick; a timed event saves BX at
; +0C, loads countdown := duration and ends the tick.
;   00..7F note    timed. Store +00, send the old key-off packet, compute and
;                  key on the new pitch.
;   80     NEXT    advance the order list (0415) and continue in the new pattern.
;   81     OFF     timed. Send the key-off packet, clear the slide.
;   82     HOLD    timed. Nothing sent; the previous note keeps sounding.
;   83     STOP    stop all music channels, clear ED/EE (no shipped stream uses it).
;   84 xx  TRANSPOSE  +12 := xx; takes effect at the next pitch computation.
;   85     END     send the key-off packet, mode := 0; the channel stops.
;   86/87  SLIDE   +13 := 01 / FF (effect streams only).
;   88..AF         not commands: out-of-table jump, see 01EA.
;   B0..BF xx LEVEL  set operator levels from xx (low nibble of the token ignored).
;   C0..DF INSTRUMENT  select record token-C0 of the bank and program it.
;   E0..FF DURATION   +11 := token-DF (1..32 ticks).
; Shipped data: 378 score patterns all end with 80; 18 effect streams all end
; with 85; tokens 83 and 88..AF never occur; no instrument ID 0 or above 10h.
;
; ---------------------------------------------------------------------------
; Instrument record: 16 bytes, bank + 16*(ID-1)
; ---------------------------------------------------------------------------
;   +00/+01 OPL 60h+op0 / 60h+op1  attack/decay
;   +02/+03 OPL 80h+op0 / 80h+op1  sustain level/release rate
;   +04/+05 OPL 20h+op0 / 20h+op1  AM/vibrato/sustain/KSR/multiplier
;   +06/+07 OPL E0h+op0 / E0h+op1  waveform
;   +08     transpose copied to record +12
;   +09     OPL C0h+channel        feedback/connection
;   +0A     op0 (modulator) volume 00..7F
;   +0B     op1 (carrier) volume offset: carrier volume = +0A + +0B (mod 80h)
;   +0C     key-scale bits: bits 5..4 -> op0 KSL, bits 1..0 -> op1 KSL
;   +0D     unread
;   +0E     release point: key off when this many ticks remain (0 = never)
;   +0F     unread
; Volumes go through LevelToAttenuation (08A7): register 40h+op =
; (3Fh - volume/2) | KSL<<6. Instrument ID 0 would select bank+1F0h.
;
; ---------------------------------------------------------------------------
; Pitch (WriteChannelPitch 0349)
; ---------------------------------------------------------------------------
; n = (note + transpose + 4) mod 256; block = octave[n]-1 (NoteOctave 0AA7);
; F = word FrequencyTable[0927 + 20h*semitone[n]] (NoteSemitone 0B07). A
; negative F (rows 7..11) adds one block; a block of -1 (octave 0) becomes 0
; with F halved by an arithmetic shift. A0h+channel := low(F); B0h+channel := (high(F)&3)|block<<2 with key-on
; 20h; the same packet without key-on is saved at +08. n is not range checked:
; shipped data reaches n=F5,F7,F8,FB,FC, which read song header and order bytes
; as octave/semitone (listed at song 01). Only word 0 of each frequency row is
; ever selected.
;
; ---------------------------------------------------------------------------
; OPL access (WriteOplRegister 0559)
; ---------------------------------------------------------------------------
; AL = register, AH = value, port = word [08A3] (0388). OUT port,AL; 12 reads
; of port (address delay); OUT port+1,AH; 47 reads of port+1 (data delay).
; No status polling. Preserves every register except AL (last port read) and
; arithmetic flags from INC DX (CF preserved). Song start writes 01=20 (waveform
; select enable), BD=C0 (AM and vibrato depth, melodic mode), 08=00, 04=21.
; Reset writes the 27 packets of ResetOplPackets: release rate F/sustain 0 on
; all 18 operators and key-off on channels 0..8.
;
; ---------------------------------------------------------------------------
; Classification summary
; ---------------------------------------------------------------------------
; Code in 0000..059F is reached from the INT 61h entry; small tables sit between
; routines at 006D, 00ED and 03EA. The NOPs after many instructions are MASM
; forward-reference padding and execute as NOPs. 05A0..05A7 (an OPL status-read
; helper shape) and the 90h byte at 0014 have no incoming edge and stay UNKNOWN. 0660..08A2 is data of Sound Images' stand-alone test jukebox (menu,
; keyboard map, error message) that this image never reads. Everything from
; 0B6E is score/effect payload, fully partitioned into directory, headers,
; order lists, patterns, instrument banks and effect streams below. No payload
; byte has a writer in the driver.
;
bits 16
org 0
; Ledger aliases (older or secondary names of the labels below).
adlib_loc_0022 equ adlib_SetCommand3Latch
adlib_loc_002A equ adlib_SetCommand4Latch
adlib_loc_0032 equ adlib_SetCommand5Latch
adlib_loc_003A equ adlib_ResetService
adlib_loc_00A3 equ adlib_DetectService
adlib_loc_0115 equ adlib_UpdateService
adlib_sub_0177 equ adlib_AdvanceChannel
adlib_sub_01B3 equ adlib_FinishTimedEvent
adlib_sub_01C0 equ adlib_KeyOffTimedEvent
adlib_sub_0339 equ adlib_StepChannelPitch
adlib_sub_0349 equ adlib_WriteChannelPitch
adlib_sub_03AA equ adlib_StopMusicChannels
adlib_sub_03CA equ adlib_ReleaseBeforeNextEvent
adlib_sub_0415 equ adlib_AdvanceOrder
adlib_sub_041F equ adlib_EnterPattern
adlib_sub_0430 equ adlib_SetTranspose
adlib_sub_043A equ adlib_EndChannel
adlib_sub_0447 equ adlib_SetAscendingPitchStep
adlib_sub_044F equ adlib_SetDescendingPitchStep
adlib_sub_0457 equ adlib_ProcessSongRequest
adlib_sub_051C equ adlib_ProcessEffectRequest
adlib_sub_0559 equ adlib_WriteOplRegister
adlib_FrequencyRowStart00 equ adlib_FrequencyTable
adlib_Instrument0DFA equ adlib_Song01InstrumentBank
adlib_Instrument10AC equ adlib_Song02InstrumentBank
adlib_Instrument13A5 equ adlib_Song03InstrumentBank
adlib_Instrument16DF equ adlib_Song04InstrumentBank
adlib_Instrument1BEC equ adlib_Song05InstrumentBank
adlib_Instrument1FAB equ adlib_Song06InstrumentBank
adlib_Instrument25B7 equ adlib_Song07InstrumentBank
adlib_Instrument2B16 equ adlib_Song08InstrumentBank
adlib_Instrument2E7D equ adlib_Song09InstrumentBank
adlib_Instrument3655 equ adlib_Song0AInstrumentBank
adlib_Instrument3B68 equ adlib_Song0BInstrumentBank
adlib_UnusedInstrument3E50 equ adlib_Song0CInstrumentBank
adlib_Instrument4103 equ adlib_Song0DInstrumentBank
adlib_Instrument4337 equ adlib_Song0EInstrumentBank
adlib_Instrument4677 equ adlib_Song0FInstrumentBank
adlib_Instrument493B equ adlib_Song10InstrumentBank
adlib_Instrument4BF7 equ adlib_Song11InstrumentBank
adlib_Instrument4E53 equ adlib_Song12InstrumentBank
adlib_Instrument503D equ adlib_Song13InstrumentBank
adlib_Instrument52D7 equ adlib_Song14InstrumentBank
adlib_Instrument548F equ adlib_Song15InstrumentBank
adlib_Instrument54E3 equ adlib_EffectInstrumentBank
adlib_EffectDirectoryBase equ adlib_EffectDirectory
; ---------------------------------------------------------------------------
; INT 61h entry: dispatch on AH.
; AH=0 -> UpdateService, 1 -> DetectService, 2 -> ResetService, 3/4/5 -> the
; three latch setters; any other AH falls to the IRET at 0021 after five DEC AH
; (AH returned as AH-5, AL and all other registers untouched).
; Flags inside the driver: AND AH,AH clears CF/OF and sets ZF/SF/PF (AF is
; undefined); each DEC sets AF/ZF/SF/PF/OF and keeps CF. None of this reaches
; the caller: IRET restores the FLAGS word pushed by INT 61h on the caller's
; stack. The native prefix in c/sound_latches.c implements this dispatcher and
; the three setters (docs/sound-latches.md); for AH=0/1/2 it stops at the
; service labels, whose bodies are c/adlib_engine.c (composed by
; lmn_adlib_int61_adapter). The services see AH already reduced to 0.
; ---------------------------------------------------------------------------
adlib_InterruptEntry:
    db 0x22,0xe4 ; ENCODED: and ah,ah (NASM selects different opcode/operand width) ; @00000
    jnz adlib_loc_0007 ; @00002
    jmp adlib_UpdateService ; @00004
adlib_loc_0007:
    dec ah ; @00007
    jnz adlib_loc_000E ; @00009
    jmp adlib_DetectService ; @0000B
; The opcode byte FE of this DEC AH is also read as data: a channel whose
; instrument pointer is still the loaded 0000 reads 0000+0E here as its release
; comparator (03D3). With durations of 1..32 ticks the remaining countdown is
; never FE, so such a channel never releases early.
adlib_loc_000E:
    dec ah ; @0000E
    jnz adlib_loc_0015 ; @00010
    jmp short adlib_ResetService ; @00012
; Byte 90h after the two-byte JMP SHORT at 0012. It is the filler MASM leaves
; when a forward JMP, reserved as three bytes, turns out to be short. No branch,
; fall-through or table reaches it and nothing reads it. It looks like code but
; has no incoming edge, so its kind stays UNKNOWN; no behavior depends on it.
; UNKNOWN [0014,0015): unresolved bytes
    db 0x90 ; @00014
adlib_loc_0015:
    dec ah ; @00015
    jz adlib_SetCommand3Latch ; @00017
    dec ah ; @00019
    jz adlib_SetCommand4Latch ; @0001B
    dec ah ; @0001D
    jz adlib_SetCommand5Latch ; @0001F
; Unrecognized AH (06..FF): return with AH = incoming AH - 5.
adlib_UnhandledCommandReturn:
    iret ; @00021
; ---------------------------------------------------------------------------
; AH=03/04/05 latch setters: store AL into ED / F0 / EE and IRET.
; PUSH DS / PUSH CS / POP DS selects the driver segment for the store; the final
; POP DS restores the caller's DS from the stack word. No validation; flags are
; unchanged and the caller's flags come back from the interrupt frame.
; ---------------------------------------------------------------------------
adlib_SetCommand3Latch:
    push ds ; @00022
    push cs ; @00023
    pop ds ; @00024
    mov [adlib_Command3Latch],al ; @00025
    pop ds ; @00028
adlib_Command3Return:
    iret ; @00029
adlib_SetCommand4Latch:
    push ds ; @0002A
    push cs ; @0002B
    pop ds ; @0002C
    mov [adlib_Command4Latch],al ; @0002D
    pop ds ; @00030
adlib_Command4Return:
    iret ; @00031
adlib_SetCommand5Latch:
    push ds ; @00032
    push cs ; @00033
    pop ds ; @00034
    mov [adlib_Command5Latch],al ; @00035
    pop ds ; @00038
adlib_Command5Return:
    iret ; @00039
; ---------------------------------------------------------------------------
; AH=02 ResetService: stop music and silence the chip.
; 1. StopMusicChannels with the current channel count [B6C] (loaded value 1,
;    so before the first song only record 0 is stopped): key-off packet and
;    mode 0 for those records, ED and EE cleared.
; 2. Send the 27 register/value words of ResetOplPackets (006D) through
;    WriteOplRegister: release rate F / sustain level 0 on all 18 operators and
;    key-off on channels 0..8. The words are read with LODSW, so DF must be 0
;    (the driver never changes DF; no caller passes DF=1).
; 3. Clear the mode byte of all nine records.
; Not touched: the pending effect F0 (it is granted at the next update), EF,
; tempo, phase, bank pointer, channel count and all other record fields.
; MOV DX,0388 at 0045 is not used as the port: WriteOplRegister always loads
; [08A3]. Saves and restores DS/AX/DI/SI/CX/DX; BX, BP and ES are untouched.
; ---------------------------------------------------------------------------
adlib_ResetService:
    push ds ; @0003A
    push ax ; @0003B
    push di ; @0003C
    push si ; @0003D
    push cx ; @0003E
    push dx ; @0003F
    push cs ; @00040
    pop ds ; @00041
    call adlib_StopMusicChannels ; @00042
    mov dx,0x388 ; @00045
    lea si,[0x6d] ; @00048
    mov cx,0x1b ; @0004C
adlib_loc_004F:
    lodsw ; @0004F
    call adlib_WriteOplRegister ; @00050
    loop adlib_loc_004F ; @00053
    mov di,0x5ac ; @00055
    mov cx,0x9 ; @00058
adlib_loc_005B:
    mov byte [di+0x10],0x0 ; @0005B
    nop ; @0005F
    add di,byte +0x14 ; @00060
    nop ; @00063
    loop adlib_loc_005B ; @00064
    pop dx ; @00066
    pop cx ; @00067
    pop si ; @00068
    pop di ; @00069
    pop ax ; @0006A
    pop ds ; @0006B
    iret ; @0006C
; ResetOplPackets: 27 (register, value) words for ResetService. Each line sets
; release rate F / sustain 0 (value 0F) on two operator slots and keys off one
; channel (B0h+n = 00); together all 18 slots and channels 0..8.
; STORED [006D,00A3): lookup_table
adlib_ResetOplPackets:
    db 0x80,0x0f,0x8b,0x0f,0xb0,0x00 ; @0006D
    db 0x81,0x0f,0x8c,0x0f,0xb1,0x00 ; @00073
    db 0x82,0x0f,0x8d,0x0f,0xb2,0x00 ; @00079
    db 0x83,0x0f,0x90,0x0f,0xb3,0x00 ; @0007F
    db 0x84,0x0f,0x91,0x0f,0xb4,0x00 ; @00085
    db 0x85,0x0f,0x92,0x0f,0xb5,0x00 ; @0008B
    db 0x88,0x0f,0x93,0x0f,0xb6,0x00 ; @00091
    db 0x89,0x0f,0x94,0x0f,0xb7,0x00 ; @00097
    db 0x8a,0x0f,0x95,0x0f,0xb8,0x00 ; @0009D
; ---------------------------------------------------------------------------
; AH=01 DetectService: standard AdLib timer test.
; Reset both OPL timers and the IRQ flag (04=60, 04=80) and read status 1; load
; timer 1 with FF (02=FF) and start it (04=21); busy-wait 012Ch LOOP iterations;
; read status 2; reset the timers again (04=60, 04=80). A card is present when
; (status1 & E0)==0 and (status2 & E0)==C0: then AL=01, else AL=00.
; The status reads use the literal port 0388 in DX; the register writes go
; through WriteOplRegister and its [08A3] port word.
; Returns AH=21, BX=8000h|(status1 & E0), CX=0, DX=0388; DS restored, SI, DI,
; BP and ES untouched. The wait is a CPU-speed loop, not a timed delay.
; ---------------------------------------------------------------------------
adlib_DetectService:
    push ds ; @000A3
    push cs ; @000A4
    pop ds ; @000A5
    mov dx,0x388 ; @000A6
    mov ax,0x6004 ; @000A9
    call adlib_WriteOplRegister ; @000AC
    mov ax,0x8004 ; @000AF
    call adlib_WriteOplRegister ; @000B2
    in al,dx ; @000B5
    push ax ; @000B6
    mov ax,0xff02 ; @000B7
    call adlib_WriteOplRegister ; @000BA
    mov ax,0x2104 ; @000BD
    call adlib_WriteOplRegister ; @000C0
    mov cx,0x12c ; @000C3
adlib_loc_00C6:
    loop adlib_loc_00C6 ; @000C6
    in al,dx ; @000C8
    push ax ; @000C9
    mov ax,0x6004 ; @000CA
    call adlib_WriteOplRegister ; @000CD
    mov ax,0x8004 ; @000D0
    call adlib_WriteOplRegister ; @000D3
    pop ax ; @000D6
    pop bx ; @000D7
    and al,0xe0 ; @000D8
    and bl,0xe0 ; @000DA
    db 0x22,0xdb ; ENCODED: and bl,bl (NASM selects different opcode/operand width) ; @000DD
    jnz adlib_loc_00E9 ; @000DF
    cmp al,0xc0 ; @000E1
    jnz adlib_loc_00E9 ; @000E3
    mov al,0x1 ; @000E5
    pop ds ; @000E7
    iret ; @000E8
adlib_loc_00E9:
    db 0x32,0xc0 ; ENCODED: xor al,al (NASM selects different opcode/operand width) ; @000E9
    pop ds ; @000EB
    iret ; @000EC
; Request latches (see the header): ED pending song ID.
; STORED [00ED,00F1): runtime_data
adlib_Command3Latch:
    db 0x00 ; @000ED
; EE current song ID, 0 when no song is current.
adlib_Command5Latch:
    db 0x00 ; @000EE
; EF song-request scratch, nonzero only inside ProcessSongRequest.
adlib_SongRequestScratch:
    db 0x00 ; @000EF
; F0 pending effect ID.
adlib_Command4Latch:
    db 0x00 ; @000F0
; Credit text; no reader identified.
; STORED [00F1,0115): embedded_resource
    db 'AdLib Music by Sound Images (c) 1991' ; @000F1
; ---------------------------------------------------------------------------
; AH=00 UpdateService: one engine step (see the cadence section of the header).
; Saves AX/BX/CX/DX/DI/SI/DS/ES, sets DS=ES=CS. Order: ProcessSongRequest,
; ProcessEffectRequest, DEC tempo phase, AdvanceChannel for all nine records in
; ascending address order (DI reloaded before each call), then reload the phase
; from the tempo reload if it reached 0. DX is NOT reloaded: until a C token in
; this update programs an instrument, DX still holds the caller's value, which
; matters to B0..BF level tokens (see SetOperatorLevels).
; ---------------------------------------------------------------------------
